sql.smartlist.add:
insert into flow.smartlist (name, company_object_type_id, shared, owner_id, created_by_id)
values (:name, :companyObjectTypeId, false, :ownerId, :createdById)
returning id;

sql.smartlist.addField:
insert into flow.smartlist_field_assignment (smartlist_id, smartlist_field_id, custom_field_group_assignment_id, created_by_id, display_order, process_step_id)
values (:smartlistId, :smartlistFieldId, :customFieldGroupAssignmentId, :createdById, :displayOrder, :processStepId)
returning id;

sql.smartlist.addRequirement:
insert into flow.smartlist_requirement (smartlist_id, process_step_id, custom_field_group_assignment_id, operator_type_id, requirement_value, secondary_requirement_value, data_type_requirement_id, display_order, created_by_id, smartlist_field_id)
values (:smartlistId, :processStepId, :customFieldGroupAssignmentId, :operatorTypeId, :requirementValue, :secondaryRequirementValue, :dataTypeRequirementId, :displayOrder, :userId, :smartlistFieldId)
returning id;
